const parts = (value: string) => value.split("~").map(x => x.trim());
export const expandedVocabularyBank: (VocabularyEntry & { source: "ai"; quality: "ai-unreviewed" })[] = Object.entries(blocks).flatMap(([topic, block]) => block.trim().split("\n").map((line, i) => {
  const fields = line.split("|");
  if (fields.length !== 11 || fields.some(x => !x.trim())) throw new Error(`Invalid x3 vocabulary ${topic}/${i + 1}`);
  const [word, meaning, definition, ipa, partOfSpeech, cefr, collocations, examples, family, commonError, synonyms] = fields as [string, string, string, string, string, Cefr, string, string, string, string, string];
  return { id: `fresh-x3-v-${topic.toLowerCase()}-${String(i + 1).padStart(2, "0")}`, word, meaning, definition, ipa, partOfSpeech, cefr, topic, collocations: parts(collocations), examples: parts(examples), family: parts(family), commonError, synonyms: parts(synonyms), register: cefr === "C1" ? "academic" : "neutral", source: "ai", quality: "ai-unreviewed" };
}));
